function testProcessNumbers() {
  // Test normal operation
  const result1 = processNumbers([1, 2, 3, 4, 5, 6]);
  assert.deepEqual(result1, [4, 8, 12], 'Should filter even numbers and multiply by 2');

  // Test empty array
  const result2 = processNumbers([]);
  assert.deepEqual(result2, [], 'Should handle empty array');

  // Test null/undefined
  const result3 = processNumbers(null);
  assert.deepEqual(result3, [], 'Should handle null input');

  // Test mixed types
  const result4 = processNumbers([1, 'hello', 2, null, 4]);
  assert.deepEqual(result4, [4, 8], 'Should handle mixed types');

  // Test odd numbers only
  const result5 = processNumbers([1, 3, 5]);
  assert.deepEqual(result5, [], 'Should return empty array for odd numbers only');
}

function testUserManager() {
  const manager = new UserManager();

  // Test adding valid user
  const user1 = { id: 1, name: 'John Doe', email: 'john@example.com', age: 30 };
  manager.addUser(user1);
  assert.deepEqual(manager.getUserById(1), user1, 'Should add and retrieve user');

  // Test adding user with invalid email
  const invalidUser = { id: 2, name: 'Jane', email: 'invalid-email', age: 25 };
  assert.throws(() => manager.addUser(invalidUser), Error, 'Should throw error for invalid email');

  // Test adding user with invalid age
  const invalidAgeUser = { id: 3, name: 'Bob', email: 'bob@example.com', age: -5 };
  assert.throws(() => manager.addUser(invalidAgeUser), Error, 'Should throw error for negative age');

  // Test updating user
  manager.updateUser(1, { age: 31 });
  assert.equal(manager.getUserById(1).age, 31, 'Should update user age');

  // Test deleting user
  manager.deleteUser(1);
  assert.equal(manager.getUserById(1), undefined, 'Should delete user');

  // Test getting all users
  const user2 = { id: 4, name: 'Alice', email: 'alice@example.com', age: 28 };
  manager.addUser(user2);
  assert.equal(manager.getAllUsers().length, 1, 'Should return all users');
}
